		private bool PostCheckChosenSpawnTile(int spawnTileX, int spawnTileY, int tileType, int wallType)
		{
			if (ZoneDungeon && (!Main.tileDungeon[tileType] || wallType == 0))
			{
				return false;
			}
			if (Main.dualDungeonsSeed && Main.tile[spawnTileX, spawnTileY].type == 48)
			{
				return false;
			}
			if (Main.tile[spawnTileX, spawnTileY - 1].liquid > 0 && Main.tile[spawnTileX, spawnTileY - 2].liquid > 0 && !Main.tile[spawnTileX, spawnTileY - 1].lava())
			{
				if (Main.tile[spawnTileX, spawnTileY - 1].shimmer())
				{
					return false;
				}
				if (Main.tile[spawnTileX, spawnTileY - 1].honey())
				{
					return false;
				}
			}
			if ((tileType == 477 || tileType == 492) && !Main.bloodMoon && !Main.eclipse && Main.invasionType <= 0 && !Main.pumpkinMoon && !Main.snowMoon && !Main.slimeRain && Main.rand.Next(100) < 10)
			{
				return false;
			}
			return true;
		}

