		private static int GetGnomeChance()
		{
			int num = 10;
			if (WorldGen.Skyblock.lowTiles)
			{
				if (Main.remixWorld)
				{
					num = 20;
				}
				else
				{
					num *= 20;
					if (AnyNPCs(624))
					{
						num *= 20;
					}
				}
			}
			if (Main.remixWorld)
			{
				num /= 2;
			}
			return num;
		}

		public static bool HasTileSpawnSpace(int spawnTileX, int spawnTileY)
		{
			//IL_001c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			Rectangle val = new Rectangle(spawnTileX - spawnSpaceX / 2, spawnTileY - spawnSpaceY, spawnSpaceX, spawnSpaceY);
			if (WorldGen.InWorld(val))
			{
				return CanSpawnInTiles(val);
			}
			return false;
		}

		public static bool CanSpawnInTiles(Rectangle tileRect)
		{
			for (int i = tileRect.Left; i < tileRect.Right; i++)
			{
				for (int j = tileRect.Top; j < tileRect.Bottom; j++)
				{
					if (!CanSpawnInTile(i, j))
					{
						return false;
					}
				}
			}
			return true;
		}

		public static bool CanSpawnInTile(int x, int y)
		{
			if (Main.tile[x, y].nactive() && Main.tileSolid[Main.tile[x, y].type])
			{
				return false;
			}
			if (Main.tile[x, y].anyLava())
			{
				return false;
			}
			return true;
		}

		public static bool CheckNotSpawningOnScreen(int spawnTileX, int spawnTileY)
		{
			//IL_000e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0050: Unknown result type (might be due to invalid IL or missing references)
			//IL_0067: Unknown result type (might be due to invalid IL or missing references)
			//IL_0096: Unknown result type (might be due to invalid IL or missing references)
			//IL_009d: Unknown result type (might be due to invalid IL or missing references)
			Rectangle val = new Rectangle(spawnTileX * 16, spawnTileY * 16, 16, 16);
			int num = sWidth / 2;
			int num2 = sHeight / 2;
			for (int i = 0; i < 255; i++)
			{
				Player player = Main.player[i];
				if (player.active && (!Main.dualDungeonsSeed || !player.insideUnbreakableWalls))
				{
					Rectangle val2 = new Rectangle((int)(player.Center.X - (float)num - (float)safeRangeX), (int)(player.Center.Y - (float)num2 - (float)safeRangeY), sWidth + safeRangeX * 2, sHeight + safeRangeY * 2);
					if (val.Intersects(val2))
					{
						return false;
					}
				}
			}
			return true;
		}

		public static bool Spawning_SandstoneCheck(int x, int y)
		{
			if (!WorldGen.InWorld(x, y, 10))
			{
				return false;
			}
			int num = 0;
			for (int i = 0; i < 8; i++)
			{
				Tile tile = Main.tile[x, y + i];
				if (!tile.active() || !TileID.Sets.Conversion.Sand[tile.type])
				{
					break;
				}
				num++;
				for (int j = 1; j <= 4; j++)
				{
					tile = Main.tile[x + j, y + i];
					if (!tile.active() || !TileID.Sets.Conversion.Sand[tile.type])
					{
						break;
					}
					num++;
				}
				for (int k = 1; k <= 4; k++)
				{
					tile = Main.tile[x - k, y + i];
					if (!tile.active() || !TileID.Sets.Conversion.Sand[tile.type])
					{
						break;
					}
					num++;
				}
			}
			if (Main.remixWorld)
			{
				return num >= 10;
			}
			return num >= 40;
		}

		public static bool Spawning_FlyingAntlionCheck(int x, int y)
		{
			if (!WorldGen.InWorld(x, y, 10))
			{
				return false;
			}
			for (int i = 0; i < 50; i++)
			{
				if (y - i < 10)
				{
					return true;
				}
				Tile tile = Main.tile[x, y - i];
