		public static void FindGroundTile(int x, int y, out int groundTileY)
		{
			groundTileY = y;
			if (TileID.Sets.InheritTypeOfTileBelowForNPCSpawning[Main.tile[x, groundTileY].type] && IsValidSpawningGroundTile(x, y + 1))
			{
				groundTileY = y + 1;
			}
			if (IsValidSpawningGroundTile(x, y))
			{
				return;
			}
			for (int i = y + 1; i < y + 30; i++)
			{
				if (IsValidSpawningGroundTile(x, i))
				{
					groundTileY = i;
					break;
				}
			}
		}

