				if (tile != null && tile.active() && TileID.Sets.IsATreeTrunk[tile.type])
				{
					int num2 = tile.frameX / 22;
					int num3 = tile.frameY / 66;
					if (((num2 == 3 && num3 == 0) || (num2 == 3 && num3 == 3) || (num2 == 4 && num3 == 1) || (num2 == 4 && num3 == 3) || (num2 == 2 && num3 == 3)) && Main.rand.Next(num) == 0)
					{
						treeBranchX = i;
						treeBranchY = j;
