	internal static NPC NewNPCInstanceInSlot(int slot, byte generation = 0)
	{
		if (Main.netMode == 2 && Main.npc[slot].spawnNeedsSyncing)
		{
			NetMessage.SendData(23, -1, -1, null, slot);
		}
		if (Main.netMode == 1)
		{
			Invariant.Assert(generation != 0, "NewNPCInstanceInSlot called on client without generation?");
		}
		else
		{
			generation = (byte)(Main.npc[slot].generation + 1);
			if (generation == 0)
			{
				generation++;
			}
		}
		NPC nPC = new NPC();
		Main.npc[slot] = nPC;
		nPC.whoAmI = slot;
		nPC.generation = generation;
		ResetNPCSlotData(slot);
		return nPC;
	}

	public static int NewNPC(IEntitySource source, int X, int Y, int Type, int Start = 0, float ai0 = 0f, float ai1 = 0f, float ai2 = 0f, float ai3 = 0f, int Target = 255)
