	public int StrikeNPCNoInteraction(int Damage, float knockBack, int hitDirection)
	{
		return StrikeNPC(Damage, knockBack, hitDirection, crit: false, fromNet: false, 255);
	}

	public int StrikeNPC(int Damage, float knockBack, int hitDirection, bool crit = false, bool fromNet = false, int owner = -1)
	{
		if (owner < 0)
		{
			owner = Main.myPlayer;
		}
		if (Main.onlyShimmerOceanWorlds && type == 680 && GivenName == "Slimefors")
		{
			return 0;
		}
		if (!active || life <= 0)
		{
			return 0;
		}
		bool condition = Damage >= 9999 && owner == 255;
		if (!fromNet)
		{
			if (Main.netMode == 1 && owner != Main.myPlayer)
			{
				Invariant.Assert(owner == 255, "Simulated strike from another client {0}? ({1})", owner, this);
				Invariant.Assert(condition, "Non instant-kill strike not sent to server? ({0})", this);
			}
			else
			{
				if (_currentStrikePendingDamage != null)
				{
					Invariant.Assert(condition: false, "Nested strikes not supported");
					return 0;
				}
				NetMessage.SendData(28, -1, -1, null, whoAmI, Damage, knockBack, hitDirection, crit.ToInt());
				if (Main.netMode == 1)
				{
					_currentStrikePendingDamage = PushPendingDamage(this);
				}
			}
		}
		try
		{
			return StrikeNPC_Inner(Damage, knockBack, hitDirection, crit, fromNet, owner);
		}
		finally
		{
			_currentStrikePendingDamage = null;
		}
	}

