	public static bool NearSpikeBall(int x, int y)
	{
		//IL_0020: Unknown result type (might be due to invalid IL or missing references)
		//IL_006b: Unknown result type (might be due to invalid IL or missing references)
		//IL_0072: Unknown result type (might be due to invalid IL or missing references)
		Rectangle val = new Rectangle(x * 16 - 300, y * 16 - 300, 600, 600);
		for (int i = 0; i < Main.maxNPCs; i++)
		{
			if (Main.npc[i].active && Main.npc[i].aiStyle == 20)
			{
				Rectangle val2 = new Rectangle((int)Main.npc[i].ai[1], (int)Main.npc[i].ai[2], 20, 20);
