	private void UpdateNPC_UpdateGravity(out float maxFallSpeed)
	{
		maxFallSpeed = 10f;
		gravity = 0.3f;
		if (type == 258)
		{
			gravity = 0.1f;
			if (velocity.Y > 3f)
			{
				velocity.Y = 3f;
			}
		}
		else if (type == 425 && ai[2] == 1f)
		{
			gravity = 0.1f;
		}
		else if ((type == 576 || type == 577) && ai[0] > 0f && ai[1] == 2f)
		{
			gravity = 0.45f;
			if (velocity.Y > 32f)
			{
				velocity.Y = 32f;
			}
		}
		else if (type == 427 && ai[2] == 1f)
		{
			gravity = 0.1f;
			if (velocity.Y > 4f)
			{
				velocity.Y = 4f;
			}
		}
		else if (type == 426)
		{
			gravity = 0.1f;
			if (velocity.Y > 3f)
			{
				velocity.Y = 3f;
			}
		}
		else if (type == 541)
		{
			gravity = 0f;
		}
		else if (aiStyle == 7 && ai[0] == 25f)
		{
			gravity = 0f;
		}
		float num = (float)Main.maxTilesX / 4200f;
		num *= num;
		float num2 = (float)((double)(position.Y / 16f - (60f + 10f * num)) / (Main.worldSurface / 6.0));
		if ((double)num2 < 0.25)
		{
			num2 = 0.25f;
		}
		if (num2 > 1f)
		{
			num2 = 1f;
		}
		gravity *= num2;
		if (wet)
		{
			if (shimmerWet)
			{
				gravity = 0.15f;
				maxFallSpeed = 5.5f;
			}
			else if (honeyWet)
			{
				gravity = 0.1f;
				maxFallSpeed = 4f;
			}
			else
			{
				gravity = 0.2f;
				maxFallSpeed = 7f;
			}
		}
	}

