			{
				return AppearsFriendlyToHunterPotion();
			}
			return true;
		}
		return false;
	}

	public bool AppearsFriendlyToHunterPotion()
	{
		bool result = friendly || catchItem > 0 || (damage == 0 && lifeMax == 5);
		bool? flag = NPCID.Sets.HunterPotionFriendlyOverride[type];
		if (flag.HasValue)
		{
			result = flag.Value;
		}
		return result;
	}

