	private void GetShimmered()
	{
		//IL_0009: Unknown result type (might be due to invalid IL or missing references)
		//IL_008c: Unknown result type (might be due to invalid IL or missing references)
		//IL_00b2: Unknown result type (might be due to invalid IL or missing references)
		//IL_00cb: Unknown result type (might be due to invalid IL or missing references)
		if (SpawnedFromStatue)
		{
			WorldItem.ShimmerEffect(Center);
			noSpawnCycle = true;
			active = false;
			if (Main.netMode == 2)
			{
				life = 0;
				NetMessage.SendData(23, -1, -1, null, whoAmI);
			}
		}
		else if (NPCID.Sets.ShimmerTransformToNPC[type] >= 0)
		{
			Transform(NPCID.Sets.ShimmerTransformToNPC[type]);
			WorldItem.ShimmerEffect(Center);
		}
		else if (NPCID.Sets.ShimmerTransformToItem[type] >= 0)
		{
			WorldItem.SpawnShimmeredItem(GetItemSource_Misc(ItemSourceID.Shimmer), Center, 0, NPCID.Sets.ShimmerTransformToItem[type]);
			WorldItem.ShimmerEffect(Center);
			noSpawnCycle = true;
			active = false;
			if (Main.netMode == 2)
			{
				life = 0;
				NetMessage.SendData(23, -1, -1, null, whoAmI);
			}
		}
		else if (NPCID.Sets.ShimmerTownTransform[type])
		{
			ai[0] = 25f;
			ai[1] = 0f;
			ai[2] = 0f;
			ai[3] = 0f;
			netUpdate = true;
			shimmerTransparency = 0.89f;
			int num = FindBuffIndex(353);
			if (num != -1)
			{
				DelBuff(num);
			}
		}
	}

