	public void UpdateNPC_BuffSetFlags(bool lowerBuffTime = true)
	{
		for (int i = 0; i < maxBuffs; i++)
		{
			if (buffType[i] <= 0 || buffTime[i] <= 0)
			{
				continue;
			}
			if (buffType[i] == 398)
			{
				acceleratePoisons = true;
			}
			if (lowerBuffTime)
			{
				buffTime[i]--;
			}
			if (buffType[i] == 20)
			{
				poisoned = true;
			}
			if (buffType[i] == 25)
			{
				tipsy = true;
			}
			if (buffType[i] == 30)
			{
				bleeding = true;
			}
			if (buffType[i] == 375)
			{
				hemorrhage = true;
			}
			if (buffType[i] == 70)
			{
