	private void CheckLifeRegen()
	{
		if (life < lifeMax)
		{
			int num = 1;
			if (dryadWard)
			{
				num += 10;
			}
			switch (type)
			{
			case 22:
				num += 5;
				break;
			case 209:
				num += 9;
				break;
			}
			friendlyRegen += num;
			if (friendlyRegen > 180)
			{
				friendlyRegen = 0;
				life++;
				NetUpdateLowPriority();
			}
		}
	}

	public void GetImmuneTime(int fromWho, int time)
	{
		if (fromWho == -1)
		{
			for (int i = 0; i < immune.Length; i++)
			{
				immune[i] = time;
			}
		}
		else if (fromWho >= 0 && fromWho < immune.Length)
		{
			immune[fromWho] = time;
		}
	}

